-- interview-batch1-diagrams.sql — 面試題庫補圖 批次 1（q7 / q12 / q17 / q19 / q26 / q27）
-- 圖為新繪，通過兩道驗證：
--   1) 瀏覽器 getBBox+getCTM 圖字重疊實測 = 0（含 path/polyline 逐段判定）
--   2) 幾何/語意驗證器 41 條斷言全過（工作週期真的是 30%、30%/70% 交點=解析解、Pd/η 自洽…）
-- 圖內標籤用英文/符號，四個語言欄位共用同一張圖（與既有 q5/q6/q28 一致）。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。
-- 冪等：欄位已含 <svg 就跳過，重跑不會插入第二張。

-- q7：SPI 四模式時序（CPOL × CPHA）
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 262" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="262" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">SPI Modes = CPOL x CPHA</text><text x="260" y="42" fill="#888" font-size="11" text-anchor="middle">CPOL sets idle level, CPHA sets sampling edge</text><text x="8" y="79" fill="#ffc107" font-size="11">Mode 0  CPOL=0 CPHA=0</text><path d="M156,84 H198 V66 H240 V84 H282 V66 H324 V84 H366 V66 H408 V84 H450 V66 H492 V84" fill="none" stroke="#00d4ff" stroke-width="1.6"/><polygon points="194,96 202,96 198,88" fill="#00ff88"/><polygon points="278,96 286,96 282,88" fill="#00ff88"/><polygon points="362,96 370,96 366,88" fill="#00ff88"/><text x="8" y="125" fill="#ffc107" font-size="11">Mode 1  CPOL=0 CPHA=1</text><path d="M156,130 H198 V112 H240 V130 H282 V112 H324 V130 H366 V112 H408 V130 H450 V112 H492 V130" fill="none" stroke="#00d4ff" stroke-width="1.6"/><polygon points="236,142 244,142 240,134" fill="#00ff88"/><polygon points="320,142 328,142 324,134" fill="#00ff88"/><polygon points="404,142 412,142 408,134" fill="#00ff88"/><text x="8" y="171" fill="#ffc107" font-size="11">Mode 2  CPOL=1 CPHA=0</text><path d="M156,158 H198 V176 H240 V158 H282 V176 H324 V158 H366 V176 H408 V158 H450 V176 H492 V158" fill="none" stroke="#00d4ff" stroke-width="1.6"/><polygon points="194,188 202,188 198,180" fill="#00ff88"/><polygon points="278,188 286,188 282,180" fill="#00ff88"/><polygon points="362,188 370,188 366,180" fill="#00ff88"/><text x="8" y="217" fill="#ffc107" font-size="11">Mode 3  CPOL=1 CPHA=1</text><path d="M156,204 H198 V222 H240 V204 H282 V222 H324 V204 H366 V222 H408 V204 H450 V222 H492 V204" fill="none" stroke="#00d4ff" stroke-width="1.6"/><polygon points="236,234 244,234 240,226" fill="#00ff88"/><polygon points="320,234 328,234 324,226" fill="#00ff88"/><polygon points="