-- q12：Buck 工作週期 D = Vout/Vin
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 200" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="200" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Buck: D = Vout / Vin</text><path d="M120,80 H148.8 V120 H216 V80 H244.8 V120 H312 V80 H340.8 V120 H408 V80 H436.8 V120 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><text x="10" y="104" fill="#ffc107" font-size="11">V_SW</text><text x="112" y="84" fill="#ff6b6b" font-size="11" text-anchor="end">5V</text><text x="112" y="124" fill="#888" font-size="11" text-anchor="end">0V</text><text x="134" y="70" fill="#00ff88" font-size="11" text-anchor="middle">D*T</text><text x="168" y="170" fill="#888" font-size="11" text-anchor="middle">T</text><line x1="120" y1="130" x2="120" y2="152" stroke="#888" stroke-width="1"/><line x1="148.8" y1="130" x2="148.8" y2="152" stroke="#888" stroke-width="1"/><line x1="216" y1="130" x2="216" y2="152" stroke="#888" stroke-width="1"/><line x1="120" y1="140" x2="148.8" y2="140" stroke="#00ff88" stroke-width="1.4"/><line x1="120" y1="155" x2="216" y2="155" stroke="#888" stroke-width="1.4"/><text x="10" y="192" fill="#888" font-size="11">Vin=5V, Vout=1.5V  ->  D = 1.5/5 = 30%</text></svg></div>$vsq$ || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 200" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="200" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Buck: D = Vout / Vin</text><path d="M120,80 H148.8 V120 H216 V80 H244.8 V120 H312 V80 H340.8 V120 H408 V80 H436.8 V120 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><text x="10" y="104" fill="#ffc107" font-size="11">V_SW</text><text x="112" y="84" fill="#ff6b6b" font-size="11" text-anchor="end">5V</text><text x="112" y="124" fill="#888" font-size="11" text-anchor="end">0V</text><text x="134" y="70" fill="#00ff88" font-size="11" text-anchor="middle">D*T</text><text x="168" y="170" fill="#888" font-size="11" text-anchor="middle">T</text><line x1="120" y1="130" x2="120" y2="152" stroke="#888" stroke-width="1"/><line x1="148.8" y1="130" x2="148.8" y2="152" stroke="#888" stroke-width="1"/><line x1="216" y1="130" x2="216" y2="152" stroke="#888" stroke-width="1"/><line x1="120" y1="140" x2="148.8" y2="140" stroke="#00ff88" stroke-width="1.4"/><line x1="120" y1="155" x2="216" y2="155" stroke="#888" stroke-width="1.4"/><text x="10" y="192" fill="#888" font-size="11">Vin=5V, Vout=1.5V  ->  D = 1.5/5 = 30%</text></svg></div>$vsq$ || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 200" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="200" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Buck: D = Vout / Vin</text><path d="M120,80 H148.8 V120 H216 V80 H244.8 V120 H312 V80 H340.8 V120 H408 V80 H436.8 V120 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><text x="10" y="104" fill="#ffc107" font-size="11">V_SW</text><text x="112" y="84" fill="#ff6b6b" font-size="11" text-anchor="end">5V</text><text x="112" y="124" fill="#888" font-size="11" text-anchor="end">0V</text><text x="134" y="70" fill="#00ff88" font-size="11" text-anchor="middle">D*T</text><text x="168" y="170" fill="#888" font-size="11" text-anchor="middle">T</text><line x1="120" y1="130" x2="120" y2="152" stroke="#888" stroke-width="1"/><line x1="148.8" y1="130" x2="148.8" y2="152" stroke="#888" stroke-width="1"/><line x1="216" y1="130" x2="216" y2="152" stroke="#888" stroke-width="1"/><line x1="120" y1="140" x2="148.8" y2="140" stroke="#00ff88" stroke-width="1.4"/><line x1="120" y1="155" x2="216" y2="155" stroke="#888" stroke-width="1.4"/><text x="10" y="192" fill="#888" font-size="11">Vin=5V, Vout=1.5V  ->  D = 1.5/5 = 30%</text></svg></div>$vsq$ || answer_ja else answer_ja end,
