-- q17：I2C 上升時間與 Rp 上限
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 220" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="220" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">I2C Rise Time (Rp x Cb)</text><line x1="60" y1="70" x2="500" y2="70" stroke="#888" stroke-width="1" stroke-dasharray="4"/><line x1="60" y1="100" x2="500" y2="100" stroke="#888" stroke-width="1" stroke-dasharray="3"/><line x1="60" y1="140" x2="500" y2="140" stroke="#888" stroke-width="1" stroke-dasharray="3"/><path d="M60,70 H110 V170 H200" fill="none" stroke="#00d4ff" stroke-width="1.8"/><polyline points="200.0,170.0 205.0,162.0 210.0,154.6 215.0,147.9 220.0,141.7 225.0,135.9 230.0,130.7 235.0,125.8 240.0,121.3 245.0,117.2 250.0,113.5 255.0,110.0 260.0,106.8 265.0,103.8 270.0,101.1 275.0,98.7 280.0,96.4 285.0,94.3 290.0,92.3 295.0,90.5 300.0,88.9 305.0,87.4 310.0,86.0 315.0,84.7 320.0,83.5 325.0,82.5 330.0,81.5 335.0,80.5 340.0,79.7 345.0,78.9 350.0,78.2 355.0,77.6 360.0,76.9 365.0,76.4 370.0,75.9 375.0,75.4 380.0,75.0 385.0,74.6 390.0,74.2 395.0,73.9 400.0,73.6 405.0,73.3 410.0,73.0 415.0,72.8 420.0,72.6 425.0,72.4 430.0,72.2 435.0,72.0 440.0,71.8 445.0,71.7 450.0,71.6 455.0,71.4 460.0,71.3 465.0,71.2 470.0,71.1 475.0,71.0 480.0,70.9 485.0,70.9 490.0,70.8" fill="none" stroke="#00d4ff" stroke-width="1.8"/><line x1="221.4" y1="140" x2="221.4" y2="188" stroke="#ff6b6b" stroke-width="1" stroke-dasharray="3"/><line x1="272.2" y1="100" x2="272.2" y2="188" stroke="#ff6b6b" stroke-width="1" stroke-dasharray="3"/><line x1="221.4" y1="192" x2="272.2" y2="192" stroke="#00ff88" stroke-width="1.6"/><text x="516" y="64" fill="#ff6b6b" font-size="11" text-anchor="end">VDD</text><text x="516" y="94" fill="#888" font-size="11" text-anchor="end">70%</text><text x="516" y="134" fill="#888" font-size="11" text-anchor="end">30%</text><text x="10" y="120" fill="#ffc107" font-size="11