-- q19：LDO 壓降損耗與效率
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 200" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="200" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">LDO Dissipation (linear = heat)</text><rect x="200" y="60" width="120" height="56" rx="4" fill="none" stroke="#00d4ff" stroke-width="1.8"/><text x="260" y="93" fill="#00d4ff" font-size="12" text-anchor="middle" font-weight="bold">LDO</text><line x1="80" y1="88" x2="200" y2="88" stroke="#ff6b6b" stroke-width="2"/><line x1="320" y1="88" x2="450" y2="88" stroke="#00ff88" stroke-width="2"/><text x="80" y="78" fill="#ff6b6b" font-size="11">5V IN</text><text x="80" y="106" fill="#888" font-size="11">500mA</text><text x="330" y="78" fill="#00ff88" font-size="11">3.3V OUT</text><text x="330" y="106" fill="#888" font-size="11">500mA</text><line x1="260" y1="116" x2="260" y2="146" stroke="#ffc107" stroke-width="2"/><polygon points="256,146 264,146 260,154" fill="#ffc107"/><text x="272" y="142" fill="#ffc107" font-size="11">Pd = (5 - 3.3) x 0.5 = 0.85W</text><text x="80" y="178" fill="#888" font-size="11">Pin 2.5W</text><text x="200" y="178" fill="#888" font-size="11">Pout 1.65W</text><text x="330" y="178" fill="#00ff88" font-size="11">eff = 3.3/5 = 66%</text></svg></div>$vsq$ || answer else answer end,
