-- q26：RC 低通：fc 與 -3dB 轉角
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 224" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="224" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">RC Low-Pass: fc = 1/(2*pi*R*C)</text><line x1="40" y1="90" x2="70" y2="90" stroke="#888" stroke-width="1.6"/><rect x="70" y="80" width="50" height="20" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="95" y="72" fill="#00d4ff" font-size="11" text-anchor="middle">R 10k</text><line x1="120" y1="90" x2="230" y2="90" stroke="#888" stroke-width="1.6"/><circle cx="170" cy="90" r="3" fill="#888"/><line x1="170" y1="90" x2="170" y2="116" stroke="#888" stroke-width="1.6"/><line x1="152" y1="116" x2="188" y2="116" stroke="#ffc107" stroke-width="2"/><line x1="152" y1="124" x2="188" y2="124" stroke="#ffc107" stroke-width="2"/><line x1="170" y1="124" x2="170" y2="150" stroke="#888" stroke-width="1.6"/><line x1="156" y1="150" x2="184" y2="150" stroke="#888" stroke-width="1.6"/><line x1="161" y1="156" x2="179" y2="156" stroke="#888" stroke-width="1.4"/><line x1="166" y1="162" x2="174" y2="162" stroke="#888" stroke-width="1.2"/><text x="196" y="124" fill="#ffc107" font-size="11">C 10n</text><text x="10" y="94" fill="#888" font-size="11">Vin</text><text x="234" y="86" fill="#00ff88" font-size="11">Vout</text><line x1="300" y1="60" x2="300" y2="180" stroke="#888" stroke-width="1.2"/><line x1="300" y1="180" x2="500" y2="180" stroke="#888" stroke-width="1.2"/><polyline points="308,80 380,80 500,150" fill="none" stroke="#00d4ff" stroke-width="1.8"/><line x1="380" y1="80" x2="380" y2="180" stroke="#ff6b6b" stroke-width="1" stroke-dasharray="3"/><circle cx="380" cy="86" r="3.5" fill="#ff6b6b"/><text x="344" y="72" fill="#ff6b6b" font-size="11">-3dB</text><text x="430" y="96" fill="#888" font-size="11">-20dB/dec</text><text x="384" y="196" fill="#ff6b6b" font-size="11">fc 1.59kHz</text><text x="296" y="58" fill="#888" font-size="11" text-anchor="end">dB</text><text x="10" y="214" fill="#888" font-size="11">fc = 1/(2*pi*10k*10n) = 1.59kHz ; at fc: -3dB, phase -45deg</text></svg></div>$vsq$ || answer else answer end,
