-- q27：Setup / Hold 視窗
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 220" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="220" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Setup / Hold Window</text><path d="M120,80 H300 V62 H420 V80 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><path d="M120,150 H230 V132 H350 V150 H500" fill="none" stroke="#ffc107" stroke-width="1.8"/><text x="10" y="74" fill="#00d4ff" font-size="11">CLK</text><text x="10" y="144" fill="#ffc107" font-size="11">DATA</text><line x1="300" y1="50" x2="300" y2="178" stroke="#ff6b6b" stroke-width="1.2" stroke-dasharray="4"/><text x="304" y="46" fill="#ff6b6b" font-size="11">active edge</text><line x1="230" y1="176" x2="230" y2="196" stroke="#888" stroke-width="1"/><line x1="350" y1="176" x2="350" y2="196" stroke="#888" stroke-width="1"/><line x1="230" y1="190" x2="300" y2="190" stroke="#00ff88" stroke-width="1.6"/><line x1="300" y1="190" x2="350" y2="190" stroke="#ff6b6b" stroke-width="1.6"/><text x="265" y="186" fill="#00ff88" font-size="11" text-anchor="middle">t_su</text><text x="325" y="186" fill="#ff6b6b" font-size="11" text-anchor="middle">t_h</text><text x="10" y="214" fill="#888" font-size="11">data must stay stable across t_su + t_h, else metastability</text></svg></div>$vsq$ || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 220" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="220" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Setup / Hold Window</text><path d="M120,80 H300 V62 H420 V80 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><path d="M120,150 H230 V132 H350 V150 H500" fill="none" stroke="#ffc107" stroke-width="1.8"/><text x="10" y="74" fill="#00d4ff" font-size="11">CLK</text><text x="10" y="144" fill="#ffc107" font-size="11">DATA</text><line x1="300" y1="50" x2="300" y2="178" stroke="#ff6b6b" stroke-width="1.2" stroke-dasharray="4"/><text x="304" y="46" fill="#ff6b6b" font-size="11">active edge</text><line x1="230" y1="176" x2="230" y2="196" stroke="#888" stroke-width="1"/><line x1="350" y1="176" x2="350" y2="196" stroke="#888" stroke-width="1"/><line x1="230" y1="190" x2="300" y2="190" stroke="#00ff88" stroke-width="1.6"/><line x1="300" y1="190" x2="350" y2="190" stroke="#ff6b6b" stroke-width="1.6"/><text x="265" y="186" fill="#00ff88" font-size="11" text-anchor="middle">t_su</text><text x="325" y="186" fill="#ff6b6b" font-size="11" text-anchor="middle">t_h</text><text x="10" y="214" fill="#888" font-size="11">data must stay stable across t_su + t_h, else metastability</text></svg></div>$vsq$ || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 220" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="220" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Setup / Hold Window</text><path d="M120,80 H300 V62 H420 V80 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><path d="M120,150 H230 V132 H350 V150 H500" fill="none" stroke="#ffc107" stroke-width="1.8"/><text x="10" y="74" fill="#00d4ff" font-size="11">CLK</text><text x="10" y="144" fill="#ffc107" font-size="11">DATA</text><line x1="300" y1="50" x2="300" y2="178" stroke="#ff6b6b" stroke-width="1.2" stroke-dasharray="4"/><text x="304" y="46" fill="#ff6b6b" font-size="11">active edge</text><line x1="230" y1="176" x2="230" y2="196" stroke="#888" stroke-width="1"/><line x1="350" y1="176" x2="350" y2="196" stroke="#888" stroke-width="1"/><line x1="230" y1="190" x2="300" y2="190" stroke="#00ff88" stroke-width="1.6"/><line x1="300" y1="190" x2="350" y2="190" stroke="#ff6b6b" stroke-width="1.6"/><text x="265" y="186" fill="#00ff88" font-size="11" text-anchor="middle">t_su</text><text x="325" y="186" fill="#ff6b6b" font-size="11" text-anchor="middle">t_h</text><text x="10" y="214" fill="#888" font-size="11">data must stay stable across t_su + t_h, else metastability</text></svg></div>$vsq$ || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then $vsq$<div class="exam-diagram-box"><svg viewBox="0 0 520 220" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="220" fill="#0a0a1a"/><text x="260" y="22" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Setup / Hold Window</text><path d="M120,80 H300 V62 H420 V80 H500" fill="none" stroke="#00d4ff" stroke-width="1.8"/><path d="M120,150 H230 V132 H350 V150 H500" fill="none" stroke="#ffc107" stroke-width="1.8"/><text x="10" y="74" fill="#00d4ff" font-size="11">CLK</text><text x="10" y="144" fill="#ffc107" font-size="11">DATA</text><line x1="300" y1="50" x2="300" y2="178" stroke="#ff6b6b" stroke-width="1.2" stroke-dasharray="4"/><text x="304" y="46" fill="#ff6b6b" font-size="11">active edge</text><line x1="230" y1="176" x2="230" y2="196" stroke="#888" stroke-width="1"/><line x1="350" y1="176" x2="350" y2="196" stroke="#888" stroke-width="1"/><line x1="230" y1="190" x2="300" y2="190" stroke="#00ff88" stroke-width="1.6"/><line x1="300" y1="190" x2="350" y2="190" stroke="#ff6b6b" stroke-width="1.6"/><text x="265" y="186" fill="#00ff88" font-size="11" text-anchor="middle">t_su</text><text x="325" y="186" fill="#ff6b6b" font-size="11" text-anchor="middle">t_h</text><text x="10" y="214" fill="#888" font-size="11">data must stay stable across t_su + t_h, else metastability</text></svg></div>$vsq$ || answer_ko else answer_ko end
 where question like $q$%Setup Time 和 Hold Time%$q$;

-- 驗收：六列都要 zh/en 為 t（ja/ko 若原本沒譯文會是 null，屬正常）
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%SPI Mode 會有幾種格式%$q$
    or question like $q$%請算出該 Buck 線路的%$q$
    or question like $q$%目標 tr = 300ns%$q$
    or question like $q$%一個 LDO 輸入 5V，輸出 3.3V%$q$
    or question like $q$%RC 低通濾波器%$q$
    or question like $q$%Setup Time 和 Hold Time%$q$;
